const src=$input.first().json;
const body=src.body&&typeof src.body==='object'&&!Array.isArray(src.body)?src.body:src;
const rawUrl=typeof body.document_url==='string'?body.document_url.trim():'';
const requestId='noventra-pdf-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8);
const isHttps=rawUrl.toLowerCase().startsWith('https://');
const rest=isHttps?rawUrl.slice(8):'';
const slashIndex=rest.indexOf('/');
const host=(slashIndex>=0?rest.slice(0,slashIndex):rest).toLowerCase();
const pathWithQuery=slashIndex>=0?rest.slice(slashIndex):'';
const cleanPath=pathWithQuery.split('?')[0].split('#')[0];
const isBnm=isHttps&&(host==='bnm.gov.my'||host.endsWith('.bnm.gov.my'))&&cleanPath.toLowerCase().endsWith('.pdf');
const fileName=cleanPath?decodeURIComponent(cleanPath.split('/').pop()||'bnm-policy.pdf'):'bnm-policy.pdf';
const inferred=fileName.toLowerCase().endsWith('.pdf')?fileName.slice(0,-4):fileName;
const title=typeof body.title==='string'&&body.title.trim()?body.title.trim():inferred.replaceAll('-',' ').replaceAll('_',' ');
if(!isBnm||!title){
  return [{json:{valid:false,http_status:400,response:{ok:false,error:'A valid HTTPS PDF URL hosted on bnm.gov.my is required',request_id:requestId}}}];
}
return [{json:{valid:true,request_id:requestId,document_url:rawUrl,title,document_code:body.document_code||null,version_label:body.version_label||'Current version',effective_date:body.effective_date||null,publication_date:body.publication_date||null,source_org:'Bank Negara Malaysia',document_type:'policy_document',jurisdiction:'Malaysia',file_name:fileName}}];

const extracted=$input.first().json;
const request=$('Validate BNM PDF Request').first().json;
const pages=Array.isArray(extracted.text)?extracted.text:[String(extracted.text||'')];
const cleaned=pages.map((p,i)=>('[PDF page '+(i+1)+']\n'+String(p||'').replace(/\r/g,'').trim())).filter(p=>p.trim());
const documentText=cleaned.join('\n\n');
if(documentText.length<100) throw new Error('PDF extraction returned insufficient text');
if(documentText.length>450000) throw new Error('PDF text exceeds the controlled Phase 3 limit of 450000 characters');
let hash=2166136261;
for(let i=0;i<documentText.length;i++){hash^=documentText.charCodeAt(i);hash=Math.imul(hash,16777619)}
const h=(hash>>>0).toString(16).padStart(8,'0').repeat(8);
return [{json:{...request,document_text:documentText,page_count:Number(extracted.numpages||pages.length),checksum_sha256:h,parser_version:String(extracted.version||'n8n-pdf')}}];

const ai=$input.first().json;
const source=$('Normalize PDF With Page Markers').first().json;
let parsed=null;
try{parsed=JSON.parse(ai?.choices?.[0]?.message?.content||'{}')}catch(e){parsed=null}
let clauses=Array.isArray(parsed?.clauses)?parsed.clauses:[];
clauses=clauses.map((c,i)=>{
  const classification=['S','G'].includes(String(c.classification||'').toUpperCase())?String(c.classification).toUpperCase():'unclassified';
  const confidence=Math.max(0,Math.min(1,Number(c.extraction_confidence??c.confidence??0)));
  const requirementText=String(c.requirement_text||c.guidance_text||'').trim();
  const pageStart=Math.max(1,Number(c.page_start||1));
  const pageEnd=Math.max(pageStart,Number(c.page_end||pageStart));
  return {clause_number:String(c.clause_number||('AI-'+(i+1))),clause_title:c.clause_title||null,section_reference:c.section_reference||null,section_title:c.section_title||c.section_reference||null,page_start:pageStart,page_end:pageEnd,classification,requirement_text:requirementText,guidance_text:c.guidance_text?String(c.guidance_text):null,confidence,extraction_confidence:confidence,review_status:confidence>=0.85&&['S','G'].includes(classification)?'ai_extracted':'review_required'};
}).filter(c=>c.requirement_text);
if(!clauses.length){
  let currentPage=1;
  clauses=[];
  for(const raw of source.document_text.split(/\n+/)){
    const page=raw.match(/^\[PDF page (\d+)\]$/i);
    if(page){currentPage=Number(page[1]);continue}
    const m=raw.trim().match(/^(\d+(?:\.\d+)+)\s+(.{30,})$/);
    if(m) clauses.push({clause_number:m[1],clause_title:null,section_reference:m[1].split('.').slice(0,-1).join('.'),section_title:null,page_start:currentPage,page_end:currentPage,classification:'unclassified',requirement_text:m[2],guidance_text:null,confidence:0.55,extraction_confidence:0.55,review_status:'review_required'});
  }
}
if(!clauses.length) throw new Error('No regulatory clauses were extracted from the PDF');
return [{json:{title:source.title,document_code:source.document_code,source_org:source.source_org,source_url:source.document_url,file_name:source.file_name,version_label:source.version_label,effective_date:source.effective_date,publication_date:source.publication_date,document_type:source.document_type,jurisdiction:source.jurisdiction,checksum_sha256:source.checksum_sha256,request_id:source.request_id,extraction_model:'gpt-4o-mini',clauses,metadata:{extraction_method:'automatic_bnm_pdf',parser_version:source.parser_version,page_count:source.page_count,source_host:'bnm.gov.my'}}}];

const stored=$input.first().json;
const receipt=Array.isArray(stored)?stored[0]:stored;
const source=$('Normalize PDF With Page Markers').first().json;
return [{json:{http_status:receipt&&receipt.ok===false?422:200,response:{...receipt,source_url:source.document_url,file_name:source.file_name,page_count:source.page_count,ingestion_method:'automatic_bnm_pdf',model:'gpt-4o-mini'}}}];
